.product-remove {
    position: relative;
    min-width: 50px
}

.product-remove a.remove {
    font-size: 0;
    width: 26px;
    height: 26px;
    background-color: var(--primary-color);
    border-radius: 100%;
    position: relative
}

.product-remove a.remove:before,
.product-remove a.remove:after {
    content: '';
    position: absolute;
    height: 1px;
    width: 12px;
    top: 50%;
    left: 0;
    right: 0;
    margin: auto;
    background-color: #fff;
    transform-origin: 50% 50%;
    opacity: 1;
    -webkit-transition: transform ease .25s;
    -khtml-transition: transform ease .25s;
    -moz-transition: transform ease .25s;
    -ms-transition: transform ease .25s;
    -o-transition: transform ease .25s;
    transition: transform ease .25s
}

.product-remove a.remove:before {
    -webkit-transform: rotate(45deg);
    -khtml-transform: rotate(45deg);
    -moz-transform: rotate(45deg);
    -ms-transform: rotate(45deg);
    -o-transform: rotate(45deg);
    transform: rotate(45deg)
}

.product-remove a.remove:after {
    -webkit-transform: rotate(-45deg);
    -khtml-transform: rotate(-45deg);
    -moz-transform: rotate(-45deg);
    -ms-transform: rotate(-45deg);
    -o-transform: rotate(-45deg);
    transform: rotate(-45deg)
}

.product-remove a.remove:hover {
    background-color: var(--primary-color)
}

.product-remove a.remove:hover:before,
.product-remove a.remove:hover:after {
    -webkit-transform: rotate(0);
    -khtml-transform: rotate(0);
    -moz-transform: rotate(0);
    -ms-transform: rotate(0);
    -o-transform: rotate(0);
    transform: rotate(0)
}

